The total capacity leaving the source and the total capacity entering the sink are upper limits on flow. The smaller total is the better of these two limits, but other edges may limit the flow further.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{decorations.markings}
\tikzset{midarrow/.style={decoration={markings, mark=at position 0.55 with {\arrow{>}}}, postaction={decorate}}}
\coordinate (S) at (0,1.5);
\coordinate (A) at (2.6,3.0);
\coordinate (B) at (2.6,0);
\coordinate (T) at (5.6,1.5);
\draw[dashed] (4.1,-1.0) -- (4.1,4.0) node[above] {cut};
\draw[midarrow] (S) -- (A) node[midway, above left] {capacity};
\draw[midarrow] (S) -- (B);
\draw[midarrow] (A) -- (B);
\draw[midarrow] (A) -- (T);
\draw[midarrow] (B) -- (T);
\fill (S) circle (2.5pt) node[left] {$S$ (source)};
\fill (A) circle (2.5pt) node[above] {$A$};
\fill (B) circle (2.5pt) node[below] {$B$};
\fill (T) circle (2.5pt) node[right] {$T$ (sink)};
\end{tikzpicture}
[/tikz]

